INNER JOIN kids_own.TB_CM_M_ULD_PRST prst ON pblnt.pblnt_sn = prst.pblnt_sn AND (prst.del_yn IS NULL OR prst.del_yn = 'N') AND ( ( prst.inst_id IS NOT NULL AND TRIM(prst.inst_id) != '' AND LPAD(TRIM(prst.inst_id), 10, '0') IN
LPAD(TRIM(#{instId}), 10, '0')
) OR ( prst.brno IS NOT NULL AND TRIM(prst.brno) != '' AND LPAD(TRIM(prst.brno), 10, '0') IN
LPAD(TRIM(#{instId}), 10, '0')
) )
AND (pblnt.del_yn IS NULL OR pblnt.del_yn = 'N')
AND pblnt.pblnt_se_cd = #{pblntSeCd}
AND pblnt.pblnt_prgrs_stts_cd = #{pblntPrgrsSttsCd}
AND EXISTS ( SELECT 1 FROM kids_own.TB_CM_M_ULD_PRST prst_f WHERE prst_f.pblnt_sn = pblnt.pblnt_sn AND (prst_f.del_yn IS NULL OR prst_f.del_yn = 'N') AND TRIM(COALESCE(prst_f.uld_inst_prgrs_stts_cd, '')) = #{uldPrgrSttsCd}
AND ( ( prst_f.inst_id IS NOT NULL AND TRIM(prst_f.inst_id) != '' AND LPAD(TRIM(prst_f.inst_id), 10, '0') IN
LPAD(TRIM(#{instId}), 10, '0')
) OR ( prst_f.brno IS NOT NULL AND TRIM(prst_f.brno) != '' AND LPAD(TRIM(prst_f.brno), 10, '0') IN
LPAD(TRIM(#{instId}), 10, '0')
) )
)
AND pblnt.ttl_nm LIKE CONCAT('%', #{keyword}, '%')
AND pblnt.pblnt_cn LIKE CONCAT('%', #{keyword}, '%')
AND (pblnt.ttl_nm LIKE CONCAT('%', #{keyword}, '%') OR pblnt.pblnt_cn LIKE CONCAT('%', #{keyword}, '%'))
AND pblnt.pblnt_bgng_ymd >= #{pblntBgngYmd}
AND pblnt.pblnt_end_ymd <= #{pblntEndYmd}

SELECT DISTINCT pblnt.pblnt_sn, pblnt.pblnt_se_cd, pblnt.ttl_nm, pblnt.pblnt_cn, pblnt.pblnt_bgng_ymd, pblnt.pblnt_end_ymd, pblnt.pblnt_prgrs_stts_cd, pblnt.del_yn, pblnt.rgtr_id, pblnt.reg_dt, pblnt.mdfr_id, pblnt.mdfcn_dt, TRIM(COALESCE(prst.uld_inst_prgrs_stts_cd, '')) AS uld_inst_prgrs_stts_cd, TRIM(COALESCE(prst.uld_type_cd, '')) AS uld_type_cd, AS "rgtrNm" FROM kids_own.TB_CM_M_ULD_PBLNT pblnt INNER JOIN kids_own.TB_CM_M_ULD_PRST prst ON pblnt.pblnt_sn = prst.pblnt_sn AND (prst.del_yn IS NULL OR prst.del_yn = 'N') AND ( ( prst.inst_id IS NOT NULL AND TRIM(prst.inst_id) != '' AND LPAD(TRIM(prst.inst_id), 10, '0') = LPAD(TRIM(COALESCE(#{instId}, '')), 10, '0') ) OR ( prst.brno IS NOT NULL AND TRIM(prst.brno) != '' AND LPAD(TRIM(prst.brno), 10, '0') = LPAD(TRIM(COALESCE(#{instId}, '')), 10, '0') ) )
AND (pblnt.del_yn IS NULL OR pblnt.del_yn = 'N')
AND pblnt.pblnt_se_cd = #{request.pblntSeCd}
AND pblnt.pblnt_prgrs_stts_cd = #{request.pblntPrgrsSttsCd}
AND TRIM(COALESCE(prst.uld_inst_prgrs_stts_cd, '')) = #{request.uldPrgrSttsCd}
AND pblnt.ttl_nm LIKE CONCAT('%', #{request.keyword}, '%')
AND pblnt.pblnt_cn LIKE CONCAT('%', #{request.keyword}, '%')
AND (pblnt.ttl_nm LIKE CONCAT('%', #{request.keyword}, '%') OR pblnt.pblnt_cn LIKE CONCAT('%', #{request.keyword}, '%'))
AND pblnt.pblnt_bgng_ymd >= #{request.pblntBgngYmd}
AND pblnt.pblnt_end_ymd <= #{request.pblntEndYmd}
ORDER BY pblnt.reg_dt DESC LIMIT #{request.limit} OFFSET #{request.offset}

SELECT COUNT(DISTINCT pblnt.pblnt_sn)
FROM kids_own.TB_CM_M_ULD_PBLNT pblnt
INNER JOIN kids_own.TB_CM_M_ULD_PRST prst
  ON pblnt.pblnt_sn = prst.pblnt_sn
  AND (prst.del_yn IS NULL OR prst.del_yn = 'N')
  AND (
    (
      prst.inst_id IS NOT NULL AND TRIM(prst.inst_id) != ''
      AND LPAD(TRIM(prst.inst_id), 10, '0') = LPAD(TRIM(COALESCE(#{instId}, '')), 10, '0')
    )
    OR (
      prst.brno IS NOT NULL AND TRIM(prst.brno) != ''
      AND LPAD(TRIM(prst.brno), 10, '0') = LPAD(TRIM(COALESCE(#{instId}, '')), 10, '0')
    )
  )

  AND (pblnt.del_yn IS NULL OR pblnt.del_yn = 'N')

    AND pblnt.pblnt_se_cd = #{request.pblntSeCd}


    AND pblnt.pblnt_prgrs_stts_cd = #{request.pblntPrgrsSttsCd}


    AND TRIM(COALESCE(prst.uld_inst_prgrs_stts_cd, '')) = #{request.uldPrgrSttsCd}




        AND pblnt.ttl_nm LIKE CONCAT('%', #{request.keyword}, '%')


        AND pblnt.pblnt_cn LIKE CONCAT('%', #{request.keyword}, '%')


        AND (pblnt.ttl_nm LIKE CONCAT('%', #{request.keyword}, '%') OR pblnt.pblnt_cn LIKE CONCAT('%', #{request.keyword}, '%'))




    AND pblnt.pblnt_bgng_ymd >= #{request.pblntBgngYmd}


    AND pblnt.pblnt_end_ymd <= #{request.pblntEndYmd}

SELECT h.uld_stats_sn AS "uldStatsSn", h.pblnt_sn AS "pblntSn", h.ptcp_inst_sn AS "ptcpInstSn", h.uld_nocs AS "uldNocs", h.uld_cpct AS "uldCpct", h.err_nocs AS "errNocs", h.err_rt AS "errRt", h.rgtr_id AS "rgtrId", AS "rgtrNm", h.reg_dt AS "regDt" FROM kids_own.TB_CM_E_ULD_STATS_HIST h WHERE h.pblnt_sn = #{pblntSn}
AND h.ptcp_inst_sn = #{ptcpInstSn}
ORDER BY h.reg_dt DESC

SELECT COALESCE(MAX(file_seq), 0)
FROM kids_own.tb_ca_e_file_trsm
WHERE atch_file_group_id = #{atchFileGroupId}

mapper.delete:
DELETE FROM kids_own.TB_CM_E_TBL_ULD_STATS_HIST
WHERE pblnt_sn = #{pblntSn}
  AND ptcp_inst_sn = #{ptcpInstSn}
  AND err_tbl_nm = #{errTblNm}

DELETE FROM kids_own.tb_cm_e_uld_stats_hist
WHERE pblnt_sn = #{pblntSn}
  AND ptcp_inst_sn = #{ptcpInstSn}
